class A:
 def __init_subclass__(cls):
  print("hook",cls.__name__)
  cls.saved=[7]
class B(A): pass
print(B.saved[0],B.__init_subclass__.__self__ is B)

class A:
 def __init_subclass__(cls): print("A",cls.__name__)
class B(A):
 def __init_subclass__(cls): print("B",cls.__name__)
class C(B): pass

class A:
 def __init_subclass__(cls): print(cls.__name__)
class B(A): pass
class C(B): pass

class A:
 def __init_subclass__(cls):
  print("A",cls.__name__)
  super().__init_subclass__()
class B(A):
 def __init_subclass__(cls):
  print("B",cls.__name__)
  super().__init_subclass__()
class C(A):
 def __init_subclass__(cls):
  print("C",cls.__name__)
  super().__init_subclass__()
class D(B,C): pass

class A:
 def __init_subclass__(cls): print("A",cls.__name__)
class B:
 def __init_subclass__(cls): print("B",cls.__name__)
class C(A,B): pass

class A:
 @classmethod
 def __init_subclass__(cls): print(cls.__name__)
class B(A): pass

class A:
 @staticmethod
 def __init_subclass__(): print("static")
class B(A): pass

class D:
 def __get__(self,obj,owner):
  print("bind",obj is None,owner.__name__)
  def hook():
   owner.saved=[8]
   print("call",owner.__name__)
  return hook
class A: __init_subclass__=D()
class B(A): pass
print(B.saved[0])

class Call:
 def __init__(self,owner): self.owner=owner
 def __call__(self): print("call",self.owner.__name__)
class D:
 def __get__(self,obj,owner): return Call(owner)
class A: __init_subclass__=D()
class B(A): pass

class D:
 def __get__(self,obj,owner):
  print("binding")
  raise AttributeError("original")
class A: __init_subclass__=D()
class B(A): print("body")

class A:
 def __init_subclass__(cls):
  print("hook")
  raise ValueError("original")
class B(A): print("body")

class A:
 def __init_subclass__(cls):
  print("never")
  yield 7
class B(A): pass
print(B.__name__)

def decorate(cls):
 print("decorate",cls.__name__,cls.marker)
 return cls
class D:
 def __set_name__(self,owner,name):
  print("name",name,owner().identity() is owner)
  owner.marker=7
class A:
 def __init_subclass__(cls):
  print("hook",cls.marker,cls().identity() is cls)
@decorate
class B(A):
 field=D()
 def identity(self): return __class__

class A: pass
def hook(): print("replacement")
class D:
 def __set_name__(self,owner,name): A.__init_subclass__=hook
class B(A): x=D()

class A:
 def __init_subclass__(cls): print("parent")
class D:
 def __set_name__(self,owner,name): owner.__init_subclass__=None
class B(A): field=D()

class A:
 def __init_subclass__(cls): print("hook",cls.__name__)
B=type("B",(A,),{})
print(issubclass(B,A))

def hook(cls): print(cls.__name__)
A=type("A",(),{"__init_subclass__":hook})
class B(A): pass

class M(type):
 def __new__(meta,name,bases,ns):
  print("new",name)
  return type.__new__(meta,name,bases,ns)
 def __init__(cls,name,bases,ns): print("init",name)
class A(metaclass=M):
 def __init_subclass__(cls): print("hook",cls.__name__)
class B(A): print("body")

class A:
 def __init_subclass__(cls): print("never")
class M(type):
 def __new__(meta,name,bases,ns): return 7
class B(A,metaclass=M): pass
print(B)

class A:
 def __init_subclass__(cls): raise ValueError("fail")
B=7
try:
 class B(A): pass
except ValueError: print(B)

class A:
 def __init_subclass__(cls):
  print(cls.__name__)
  if cls.__name__ == "B": cls.child=type("C",(A,),{})
class B(A): pass
print(B.child.__name__)

for value in (None,[],object(),str):
 class A: method=classmethod(value)
 bound=A.method
 print(bound.__self__ is A,bound.__func__ is value)

class A:
 def __init_subclass__(cls,*,a,**kwargs):
  print("A",a)
  super().__init_subclass__(**kwargs)
class B:
 def __init_subclass__(cls,*,b):
  print("B",b)
  super().__init_subclass__()
class C(A,B,a=7,b=8): pass

def mark(label,value):
 print(label)
 return value
class A:
 def __init_subclass__(cls,**kw): print("hook",kw["x"],kw["y"])
class B(mark("base",A),x=mark("x",7),metaclass=mark("meta",type),y=mark("y",8)):
 print("body")

def deco():
 print("decorator expression")
 def apply(cls):
  print("decorate",cls.value)
  return cls
 return apply
def value():
 print("keyword")
 return 7
class A:
 def __init_subclass__(cls,*,value):
  print("hook")
  cls.value=value
@deco()
class B(A,value=value()): print("body")

def fail(): raise ValueError("keyword")
class A:
 def __init_subclass__(cls,**kwargs): print("never")
class B(A,x=fail()): print("never")

class A:
 def __init_subclass__(cls,*,x): print("never")
class B(A): print("body")

class A:
 @staticmethod
 def __init_subclass__(*,x): print(x[0])
class B(A,x=[7]): pass

class D:
 def __get__(self,obj,owner):
  print("bind",obj is None,owner.__name__)
  def hook(*,x):
   owner.saved=x
   print(x[0])
  return hook
class A: __init_subclass__=D()
class B(A,x=[7]): pass
print(B.saved[0])

class M(type):
 def __new__(meta,name,bases,ns,**kw):
  print("new",name,kw["x"][0])
  return type.__new__(meta,name,bases,ns,**kw)
 def __init__(cls,name,bases,ns,**kw):
  print("init",name,kw["x"][0])
  type.__init__(cls,name,bases,ns,**kw)
class A:
 def __init_subclass__(cls,*,x):
  print("hook",x[0])
  cls.saved=x
class B(A,x=[7],metaclass=M): pass
print(B.saved[0])

class M(type):
 def __new__(meta,name,bases,ns,*,x):
  cls=type.__new__(meta,name,bases,ns)
  cls.x=x
  return cls
 def __init__(cls,name,bases,ns,*,x): print("init",x)
class A(x=7,metaclass=M): pass
print(A.x)

class M(type):
 def __new__(meta,name,bases,ns,**kw): return type.__new__(meta,name,bases,ns)
class A(metaclass=M,x=7): pass
print(type(A) is M)

class A:
 def __init_subclass__(cls,*,x):
  print(cls.__name__,x[0])
  cls.saved=x
B=type("B",(A,),{},x=[7])
print(B.saved[0])

class A:
 def __init_subclass__(cls,*,x): print(x)
B=type.__new__(type,"B",(A,),{},x=7)
print(B.__name__)

class M(type):
 def __new__(meta,name,bases,ns,**kw):
  print("new",name,len(kw))
  return type.__new__(meta,name,bases,ns,**kw)
class A(metaclass=M):
 def __init_subclass__(cls,*,x): print("hook",x)
B=type.__new__(type,"B",(A,),{},x=7)
print(type(B) is M)

class M(type): pass
class A:
 def __init_subclass__(cls,*,x): print(x)
B=type.__call__(M,"B",(A,),{},x=7)
print(type(B) is M)

class M(type):
 def __init_subclass__(cls,*,x): print("meta",cls.__name__,x)
class N(M,x=7): pass
class A(metaclass=N): pass
print(type(A) is N)

class A:
 def __init_subclass__(cls,**kwargs):
  for key in kwargs: print(key,kwargs[key])
class B(A,z=7,a=8): pass

class A:
 def __init_subclass__(cls,*,metaclass): pass
class B(A,metaclass=type): print("body")

class A:
 def __init_subclass__(cls,**kw): print(kw["__private"])
class Outer:
 class B(A,__private=7): pass

class M(type):
 @classmethod
 def __prepare__(meta,name,bases): return {}
class A(metaclass=M): pass

class A:
 def __mro_entries__(self,bases): return ()
class B(A()): pass
